package com.lianxibu.site.service.jobs;
import static org.junit.jupiter.api.Assertions.*;
import com.lianxibu.site.domain.protocol.CanonicalJson;
import com.lianxibu.site.repository.jobs.JdbcFrozenSourcePlans;
import java.util.*;
import org.junit.jupiter.api.Test;
import org.springframework.jdbc.datasource.DataSourceTransactionManager;
import org.springframework.transaction.support.TransactionTemplate;
import tools.jackson.databind.node.ObjectNode;

class SourcePartitionObservedProofTest {
    SourcePartitionProofServiceTest f;
    FrozenSourceStagePlanServiceTest database(){return new FrozenSourceStagePlanServiceTest();}
    void setup(){f=new SourcePartitionProofServiceTest(){@Override FrozenSourceStagePlanServiceTest fixture(){return SourcePartitionObservedProofTest.this.database();}};f.setup();}
    <T>T read(java.util.function.Supplier<T> work){var tx=new TransactionTemplate(new DataSourceTransactionManager(f.f.fixture.source));tx.setReadOnly(true);return tx.execute(s->work.get());}
    @Test void ActualCompleteOriginalArchiveMatchesEveryWriterChunkWithoutNewSourceReads(){setup();int rows=f.f.count(),reads=f.f.sourceReads;assertEquals(251,f.f.original.members().size());for(var chunk:f.f.plan.chunks()){assertEquals(chunk,read(()->f.proof.requireObserved(chunk.rootId(),chunk.snapshotJson(),chunk.inputHash())));assertEquals(chunk,f.f.tx(()->f.proof.require(chunk.rootId(),chunk.snapshotJson(),chunk.inputHash())));}assertEquals(rows,f.f.count());assertEquals(reads,f.f.sourceReads);assertEquals(0,f.f.fixture.jdbc.queryForObject("SELECT SUM(call_count) FROM jobs",Integer.class));}
    @Test void RehashedWrongInputAndChangedPermanentBlockCannotReplaceOriginal(){setup();var chunk=f.f.plan.chunks().getFirst();for(String mode:List.of("member","part","owner","closed","missing","generation")){var input=(ObjectNode)CanonicalJson.parse(chunk.snapshotJson());switch(mode){case "member"->((ObjectNode)input.path("members").get(0)).put("id","fictional-other-item");case "part"->((ObjectNode)input.get(SourcePartitionPlanner.FIELD)).put("stage_part",1);case "owner"->((ObjectNode)input.get(SourcePartitionPlanner.FIELD).get("universe_ref")).put("owner_job_id","fictional-other-owner");case "closed"->((ObjectNode)input.get(SourcePartitionPlanner.FIELD)).put("extra",true);case "missing"->input.remove(SourcePartitionPlanner.FIELD);case "generation"->input.put("generation",2);}String raw=new String(CanonicalJson.bytes(input),java.nio.charset.StandardCharsets.UTF_8),hash=CanonicalJson.hash(CanonicalJson.Domain.INPUT,input);assertThrows(RuntimeException.class,()->read(()->f.proof.requireObserved(chunk.rootId(),raw,hash)));}String stamp=JdbcFrozenSourcePlans.stamp(f.f.universeRef.ownerId());f.f.fixture.jdbc.update("UPDATE jobs SET payload_json='{}',payload_hash=? WHERE owner_job_id=? AND stamp_id=? AND part_no=1",HexFormat.of().parseHex(CanonicalJson.hash(CanonicalJson.Domain.INPUT_PART,CanonicalJson.parse("{}"))),f.f.universeRef.ownerId(),stamp);assertThrows(RuntimeException.class,()->read(()->f.proof.requireObserved(chunk.rootId(),chunk.snapshotJson(),chunk.inputHash())));assertEquals(0,f.f.fixture.count("record_kind='ai_attempt'"));}
    @Test void RolesMissingIdentityHashAndCapacityAreClosed(){setup();var c=f.f.plan.chunks().getFirst();assertThrows(RuntimeException.class,()->f.proof.requireObserved(c.rootId(),c.snapshotJson(),c.inputHash()));assertThrows(RuntimeException.class,()->f.f.tx(()->f.proof.requireObserved(c.rootId(),c.snapshotJson(),c.inputHash())));assertThrows(RuntimeException.class,()->read(()->f.proof.require(c.rootId(),c.snapshotJson(),c.inputHash())));assertThrows(RuntimeException.class,()->read(()->f.proof.requireObserved("fictional-other-root",c.snapshotJson(),c.inputHash())));assertThrows(RuntimeException.class,()->read(()->f.proof.requireObserved(c.rootId(),c.snapshotJson(),"b".repeat(64))));assertThrows(RuntimeException.class,()->read(()->f.proof.requireObserved(c.rootId(),"x".repeat(1048577),c.inputHash())));f.f.fixture.jdbc.update("DELETE FROM jobs WHERE target_type='source_stage_plan'");assertThrows(RuntimeException.class,()->read(()->f.proof.requireObserved(c.rootId(),c.snapshotJson(),c.inputHash())));assertEquals(0,f.f.fixture.count("record_kind='logical_task'"));}
}
